"""Tema visual NIP compartilhado por todas as paginas."""
import streamlit as st

def aplicar_tema(titulo, descricao, selo):
    st.markdown('<style>\n:root{--nip-navy:#123653;--nip-teal:#087785;--nip-bg:#edf2f6;--nip-ink:#1c3144}\nhtml,body,[data-testid="stAppViewContainer"]{background:var(--nip-bg)!important;color:var(--nip-ink)!important;font-family:Arial,sans-serif!important}\n[data-testid="stHeader"]{background:transparent!important}\n[data-testid="stSidebar"]{background:var(--nip-navy)!important}\n[data-testid="stSidebar"] *{color:#e9f4f8}\n[data-testid="stMainBlockContainer"]{max-width:100%!important;padding:1rem 1.4rem 2rem!important}\n.nip-header{background:#123653;color:white;padding:16px 20px;border-radius:6px;display:flex;align-items:center;justify-content:space-between;gap:16px;margin:0 0 16px;box-shadow:0 2px 8px #12365322}\n.nip-header h1{font:700 19px Arial,sans-serif!important;margin:0!important;color:#fff!important}\n.nip-header small{color:#c6dbe8;font:12px Arial,sans-serif}\n.nip-chip{background:#087785;border-radius:5px;padding:10px 15px;font-weight:700;font-size:12px;white-space:nowrap}\n.stButton>button[kind="primary"],.stDownloadButton>button{background:#087785!important;border:1px solid #087785!important;color:#fff!important;border-radius:5px!important}\n.stButton>button:not([kind="primary"]){border-color:#b7cbd5!important;border-radius:5px!important}\n[data-testid="stTextArea"] textarea,[data-testid="stTextInput"] input,[data-baseweb="select"]>div{border-color:#c6d7e0!important;border-radius:5px!important}\n.metric-card,.page-card,.legend-box,.status-panel{border-color:#d8e3eb!important;box-shadow:0 2px 7px #1236530c!important}\n.page-card-header,.header-sgo,.header-mapa,.header-expurgo{background:#123653!important;color:white!important}\n.hero-title,.section-title{color:#123653!important}\n@media(max-width:850px){.nip-header{flex-direction:column;align-items:flex-start}[data-testid="stMainBlockContainer"]{padding:.7rem!important}}\n</style>', unsafe_allow_html=True)
    st.markdown(f'<div class="nip-header"><div><h1>{titulo}</h1><small>{descricao}</small></div><span class="nip-chip">{selo}</span></div>', unsafe_allow_html=True)
